    48			for _, storedFlag := range flags {
    49				flag := &Flag{
    50					Key:         storedFlag.Key,
    51					Name:        storedFlag.Name,
    52					Description: storedFlag.Description,
    53					Enabled:     storedFlag.Enabled,
    54				}
