    64						if err := json.Unmarshal([]byte(storedVariant.Attachment), &variant.Attachment); err != nil {
    65							return fmt.Errorf("decoding attachment for variant %q on flag %q: %w", storedVariant.Key, storedFlag.Key, err)
    66						}
