    78					rule := &Rule{SegmentKey: storedRule.SegmentKey, Rank: uint(storedRule.Rank)}
    79					for _, storedDistribution := range storedRule.Distributions {
    80						rule.Distributions = append(rule.Distributions, &Distribution{
    81							VariantKey: variantKeys[storedDistribution.VariantId],
    82							Rollout:    storedDistribution.Rollout,
    83						})
    84					}
    85					flag.Rules = append(flag.Rules, rule)
    86				}
