    91				break
    92			}
    93		}
    94	
    95		for offset := uint64(0); ; offset += batchSize {
    96			segments, err := e.store.ListSegments(ctx, storage.WithOffset(offset), storage.WithLimit(batchSize))
    97			if err != nil {
    98				return fmt.Errorf("getting segments: %w", err)
    99			}
   100	
   101			for _, storedSegment := range segments {
   102				segment := &Segment{
   103					Key:         storedSegment.Key,
   104					Name:        storedSegment.Name,
   105					Description: storedSegment.Description,
   106				}
