   108					segment.Constraints = append(segment.Constraints, &Constraint{
   109						Type:     storedConstraint.Type.String(),
   110						Property: storedConstraint.Property,
   111						Operator: storedConstraint.Operator,
   112						Value:    storedConstraint.Value,
   113					})
   114				}
   115				doc.Segments = append(doc.Segments, segment)
   116			}
