    32	
    33	// Import decodes a YAML document and creates all of its entities in the store.
    34	func (i *Importer) Import(ctx context.Context, r io.Reader) error {
    35		doc := new(Document)
    36		if err := yaml.NewDecoder(r).Decode(doc); err != nil {
    37			return fmt.Errorf("importing: %w", err)
    38		}
    39	
    40		createdVariants := make(map[string]*flipt.Variant)
    41		for _, f := range doc.Flags {
    42			if err := ctx.Err(); err != nil {
    43				return err
    44			}
    45			_, err := i.store.CreateFlag(ctx, &flipt.CreateFlagRequest{
    46				Key:         f.Key,
    47				Name:        f.Name,
    48				Description: f.Description,
    49				Enabled:     f.Enabled,
    50			})
    51			if err != nil {
    52				return fmt.Errorf("importing flag: %w", err)
    53			}
