    72				}
    73	
    74				variant, err := i.store.CreateVariant(ctx, &flipt.CreateVariantRequest{
    75					FlagKey:     f.Key,
    76					Key:         v.Key,
    77					Name:        v.Name,
    78					Description: v.Description,
    79					Attachment:  attachment,
    80				})
