    86		}
    87	
    88		for _, s := range doc.Segments {
    89			if err := ctx.Err(); err != nil {
    90				return err
    91			}
    92			_, err := i.store.CreateSegment(ctx, &flipt.CreateSegmentRequest{
    93				Key:         s.Key,
    94				Name:        s.Name,
    95				Description: s.Description,
    96			})
    97			if err != nil {
    98				return fmt.Errorf("importing segment: %w", err)
    99			}
   100			for _, c := range s.Constraints {
   101				if _, err := i.store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
   102					SegmentKey: s.Key,
   103					Type:       flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
   104					Property:   c.Property,
   105					Operator:   c.Operator,
   106					Value:      c.Value,
   107				}); err != nil {
   108					return fmt.Errorf("importing constraint: %w", err)
   109				}
   110			}
   111		}
   112	
   113		for _, f := range doc.Flags {
   114			for _, r := range f.Rules {
   115				if err := ctx.Err(); err != nil {
   116					return err
   117				}
   118				rule, err := i.store.CreateRule(ctx, &flipt.CreateRuleRequest{
   119					FlagKey:    f.Key,
   120					SegmentKey: r.SegmentKey,
   121					Rank:       int32(r.Rank),
   122				})
   123				if err != nil {
   124					return fmt.Errorf("importing rule: %w", err)
   125				}
   126				for _, d := range r.Distributions {
   127					variant, ok := createdVariants[f.Key+":"+d.VariantKey]
   128					if !ok {
   129						return fmt.Errorf("finding variant %q for flag %q", d.VariantKey, f.Key)
   130					}
