   136					}); err != nil {
   137						return fmt.Errorf("importing distribution: %w", err)
   138					}
   139				}
   140			}
   141		}
   142	
   143		return nil
   144	}
   145	
   146	// convert recursively changes YAML's interface-keyed maps into JSON-compatible
   147	// string-keyed maps while retaining sequence and scalar values.
   148	func convert(value interface{}) interface{} {
   149		if value == nil {
   150			return nil
   151		}
   152	
   153		rv := reflect.ValueOf(value)
   154		switch rv.Kind() {
   155		case reflect.Interface, reflect.Ptr:
   156			if rv.IsNil() {
   157				return nil
   158			}
   159			return convert(rv.Elem().Interface())
   160		case reflect.Map:
   161			if rv.IsNil() {
   162				return nil
   163			}
   164			result := make(map[string]interface{}, rv.Len())
   165			iter := rv.MapRange()
   166			for iter.Next() {
   167				result[fmt.Sprint(iter.Key().Interface())] = convert(iter.Value().Interface())
   168			}
   169			return result
   170		case reflect.Slice, reflect.Array:
   171			if rv.Kind() == reflect.Slice && rv.IsNil() {
   172				return nil
   173			}
   174			result := make([]interface{}, rv.Len())
   175			for index := 0; index < rv.Len(); index++ {
   176				result[index] = convert(rv.Index(index).Interface())
   177			}
   178			return result
   179		default:
   180			return value
   181		}
   182	}
