    18	
    19	// Variant represents a flag variant. Attachment may contain any YAML value.
    20	type Variant struct {
    21		Key         string      `yaml:"key,omitempty"`
    22		Name        string      `yaml:"name,omitempty"`
    23		Description string      `yaml:"description,omitempty"`
    24		Attachment  interface{} `yaml:"attachment,omitempty"`
    25	
    26		attachmentPresent bool
    27	}
    28	
    29	// MarshalYAML preserves an explicitly supplied null attachment while omitting
    30	// attachments which were not defined.
    31	func (v Variant) MarshalYAML() (interface{}, error) {
    32		type variantYAML struct {
    33			Key         string       `yaml:"key,omitempty"`
    34			Name        string       `yaml:"name,omitempty"`
    35			Description string       `yaml:"description,omitempty"`
    36			Attachment  *interface{} `yaml:"attachment,omitempty"`
    37		}
    38	
    39		result := variantYAML{
    40			Key:         v.Key,
    41			Name:        v.Name,
    42			Description: v.Description,
    43		}
    44		if v.Attachment != nil || v.attachmentPresent {
    45			attachment := v.Attachment
    46			result.Attachment = &attachment
    47		}
    48		return result, nil
    49	}
    50	
    51	// UnmarshalYAML records whether attachment was present, including an explicit
    52	// YAML null, so the importer can preserve it as the JSON value null.
    53	func (v *Variant) UnmarshalYAML(unmarshal func(interface{}) error) error {
    54		type variantYAML Variant
    55	
    56		var fields map[interface{}]interface{}
    57		if err := unmarshal(&fields); err != nil {
    58			return err
    59		}
    60		_, v.attachmentPresent = fields["attachment"]
    61		if err := unmarshal((*variantYAML)(v)); err != nil {
    62			return err
    63		}
    64		return nil
    65	}
